<template>
  <section class="refund-application-goods">
    <div class="section-heading"><h3>退款申请商品</h3><span class="hint">{{ schemeLabel }}</span></div>
    <article class="application-product-card">
      <div class="application-product-heading"><div><div class="application-product-title"><strong>{{ application.products[0].name }}</strong><el-tag size="small" type="info" effect="plain">{{ application.type_label }}</el-tag></div><div class="hint">SKU：{{ application.products[0].sku || '待核对' }}<span v-if="application.sales_spec"> · {{ application.sales_spec }}</span></div></div><router-link :to="{path:'/oms-order/business',query:{view:'business',orderId:refund.order_id}}" target="_blank">查看原订单</router-link></div>
      <div class="application-child-order"><span class="hint">平台子订单号</span><span>{{ application.platform_oid || '未提供' }}</span><el-button v-if="application.platform_oid" v-clipboard:copy="application.platform_oid" v-clipboard:success="copied" type="text" icon="el-icon-document-copy" aria-label="复制申请商品平台子订单号"/></div>
      <div class="application-quantities"><div><span>原购买数量</span><strong>{{ quantity(application.original_quantity) }}</strong></div><div class="application-requested"><span>本次申请数量</span><strong>{{ quantity(application.quantity) }}</strong></div><div><span>购买商品处理</span><strong>{{ label(refund.goods_action) }}</strong><span>{{ label(refund.goods_state) }}</span></div><div><span>本次商品退回安排</span><strong>{{ arrangementText }}</strong><span v-if="progress">实收 {{ progressQuantity(progress, 'accepted_quantity') }} · 入账 {{ progressQuantity(progress, 'posted_quantity') }}</span><el-button type="text" size="small" @click="$emit('open-goods')">查看商品退回进度</el-button></div></div>
      <p class="application-scope-note">申请数量使用销售单位；退回安排、仓库实收和库存入账按实际库存单位单独跟踪。赠品在下方独立展示。</p>
      <el-collapse class="application-details"><el-collapse-item title="销售金额与退款依据" name="amounts"><el-descriptions border :column="3" size="small"><el-descriptions-item v-for="field in moneyFields" :key="field[0]" :label="field[0]">{{ money(application.money[field[1]]) }}</el-descriptions-item><el-descriptions-item :label="refund.approved_version ? '已采用申请金额' : '本次申请金额'">{{ money(refund.refund_fee) }}</el-descriptions-item><el-descriptions-item label="平台最新申请金额">{{ money((refund.platform || {}).refund_fee) }}</el-descriptions-item><el-descriptions-item label="资金进度">{{ refund.funds_state === 'SUCCESS' ? '平台确认退款成功' : refund.funds_state === 'CLOSED' ? '平台申请已关闭' : '待平台处理' }}</el-descriptions-item></el-descriptions><p class="hint">原子单金额对应整行购买数量；本次退款金额由平台申请及审核方案确定。商品退款、运费退款未提供拆分时不推算。</p></el-collapse-item>
      <el-collapse-item v-if="application.kind !== 'NORMAL' || application.replacements.length" title="销售商品组成与实际退回范围" name="components"><p class="hint">原销售商品与实际履约组件分别保留；以下组件不重复计算申请数量或销售金额。</p><template v-if="application.kind === 'LUCKY_BAG'"><p>本退款已关联整袋退回 {{ application.return_units.length }} 袋<span v-if="!application.return_units.length">，具体退回原袋或组件请在退回安排中确认</span>。</p><div v-for="unit in application.return_units" :key="unit.unit_id" class="application-unit"><b>第 {{ unit.unit }} 袋</b><span class="hint"> · 原袋号 #{{ unit.unit_id }}</span><div v-for="(part,i) in unit.components" :key="i">{{ part.goods_name || part.sku_sn }} · {{ part.sku_sn }} × {{ part.quantity }} 件</div></div></template><el-table v-else-if="application.components.length" :data="application.components" size="small"><el-table-column label="组成商品" min-width="220"><template slot-scope="s">{{ s.row.goods_name || s.row.sku_sn }}<div class="hint">{{ s.row.sku_sn }}</div></template></el-table-column><el-table-column label="每套用量" width="110"><template slot-scope="s">{{ s.row.quantity }} 件</template></el-table-column></el-table><p v-if="application.kind === 'STOCKED_BUNDLE'" class="hint">按组合成品退回时以套计数；拆件退回以已确认的实际安排为准。</p><p v-if="application.replacements.length" class="hint">存在换品履约，退回时需核对实际发出的 SKU：{{ application.replacements.map(l=>l.sku_sn).join('、') }}。</p></el-collapse-item></el-collapse>
    </article>
    <div class="application-reason"><span class="hint">申请原因</span><span>{{ (refund.platform || {}).reason || '未提供' }}</span><el-tooltip content="申请数量来自平台，与实际退回安排、仓库实收分别记录。" placement="top"><i class="el-icon-info hint" aria-label="申请数量口径说明" tabindex="0"/></el-tooltip></div>
  </section>
</template>
<script>
import { refundApplication } from './refundDetailPresentation'
import { label } from './refundLabels'
import { money } from './orderAmounts'
import { progressQuantity } from './refundListPresentation'
export default {
  props: { refund: { type: Object, required: true } },
  data: () => ({ moneyFields: [['原子单销售金额', 'sales_amount'], ['原子单优惠合计', 'discount_total'], ['原子单商品实付', 'goods_payment']] }),
  computed: {
    arrangementText() { return this.progress ? '已安排 ' + progressQuantity(this.progress, 'return_quantity') : Number(this.refund.has_purchase_return) ? '尚未安排' : this.refund.review_state === 'APPROVED' || this.refund.goods_state === 'DONE' ? '无需商品退回' : '审核后确定' },
    progress() { return this.refund.purchase_progress || null },
    application() { return refundApplication(this.refund) },
    schemeLabel() { return [...new Set([this.refund.goods_action, this.refund.purpose].filter(value => value && value !== 'UNKNOWN').map(label))].join(' · ') || '待核对方案' }
  },
  methods: { label, money, progressQuantity, quantity(value) { return value == null ? '未提供' : value + ' ' + this.application.unit }, copied() { this.$message.success('平台子订单号已复制') } }
}
</script>
<style scoped>
