.application-product-card{border:1px solid #dfe7f1;border-radius:8px;padding:18px}.application-product-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.application-product-title{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:6px}.application-product-title>strong{font-size:16px;color:#29394d}.application-product-heading>a{white-space:nowrap;font-size:12px;color:#1683ff}.application-child-order{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:10px;font-size:12px;overflow-wrap:anywhere}.application-child-order .el-button{padding:2px}.application-quantities{display:grid;grid-template-columns:1fr 1fr 1.2fr 1.7fr;gap:12px;background:#f6f8fc;border-radius:6px;padding:16px;margin-top:14px}.application-quantities>div{display:flex;flex-direction:column;align-items:flex-start;gap:8px;font-size:12px;color:#758397}.application-quantities strong{font-size:15px;color:#34465e;font-weight:500}.application-requested strong{color:#1683ff;font-weight:600}.application-quantities .el-button{padding:0}.application-scope-note{color:#758397;font-size:12px;line-height:1.8;margin:10px 0}.application-unit{padding:10px 14px;background:#f6f8fc;margin:10px 0;line-height:1.8;font-size:13px}.application-details{margin-top:14px}@media(max-width:900px){.application-quantities{grid-template-columns:1fr 1fr}.application-product-heading{flex-wrap:wrap}}
</style>
